describe("Copilot workspace snapshots", () => {
  it.effect(
    "exposes project skills only for their requested cwd, never in the instance-wide snapshot",
    () =>
      Effect.gen(function* () {
        const requested: string[] = [];
        const fake = {
          start: async () => {},
          stop: async () => [],
          forceStop: async () => {},
          getStatus: async () => ({ version: "1.0.75", protocolVersion: 1 }),
          getAuthStatus: async () => ({ isAuthenticated: true }),
          listModels: async () => [],
          createSession: async () => {
            throw new Error("Discovery must not create native sessions.");
          },
          rpc: {
            skills: {
              discover: async ({ projectPaths }: { projectPaths: string[] }) => {
                const cwd = projectPaths[0]!;
                requested.push(cwd);
                return {
                  skills: [
                    {
                      name: cwd === "/project-a" ? "skill-a" : "skill-b",
                      description: "Project skill",
                      source: "project",
                      enabled: true,
                      userInvocable: true,
                      path: `${cwd}/.github/skills/SKILL.md`,
                    },
                  ],
                };
              },
            },
          },
        };
        const mock = vi
          .spyOn(NativeClient, "createClient")
          .mockReturnValue(fake as unknown as CopilotClient);
        yield* Effect.addFinalizer(() => Effect.sync(() => mock.mockRestore()));
        const instance = yield* CopilotDriver.create({
          instanceId: ProviderInstanceId.make("githubCopilot"),
          displayName: undefined,
          environment: [],
          enabled: true,
          config: settings,
        });
        const first = yield* instance.snapshotForCwd!("/project-a");
        const second = yield* instance.snapshotForCwd!("/project-b");
        assert.deepEqual(
          first.skills.map((skill) => skill.name),
          ["skill-a"],
        );
        assert.deepEqual(
          second.skills.map((skill) => skill.name),
          ["skill-b"],
        );
        assert.deepEqual((yield* instance.snapshot.getSnapshot).skills, []);
        assert.deepEqual(requested, ["/project-a", "/project-b"]);
      }).pipe(
        Effect.provideService(ProviderHost.ProviderHost, host),
        Effect.provide(McpProviderSessions.layer),
        Effect.scoped,
      ),
  );
});

import { ProviderDriverKind, type ServerProviderSkill } from "@t3tools/contracts";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import * as Option from "effect/Option";
import * as ProviderHost from "@t3tools/provider-core/server/ProviderHost";
import * as McpProviderSessions from "@t3tools/provider-core/server/McpProviderSessions";
import type { ProviderDriver, ProviderInstance } from "@t3tools/provider-core/server/driver";
import { ProviderDriverError } from "@t3tools/provider-core/server/errors";
import { makeManagedServerProvider } from "@t3tools/provider-core/server/managedProvider";
import { withInstanceIdentity } from "@t3tools/provider-core/server/instanceIdentity";
import { mergeProviderInstanceEnvironment } from "@t3tools/provider-core/server/instanceEnvironment";
import { makeManualOnlyProviderMaintenanceCapabilities } from "@t3tools/provider-core/server/maintenanceResolver";
import {
  haveProviderSnapshotSettingsChanged,
  makeProviderSnapshotSettingsSource,
} from "@t3tools/provider-core/server/snapshotSettings";
import { CopilotSettings } from "../settings.ts";
import { makeAdapter } from "./adapter.ts";
import { createClient, resolveClientConfiguration } from "./client.ts";
import { checkStatus, pendingSnapshot, skillsFromSdk } from "./status.ts";
import { makeTextGeneration } from "./textGeneration.ts";

const driverKind = ProviderDriverKind.make("githubCopilot");
const decodeSettings = Schema.decodeSync(CopilotSettings);
export type CopilotDriverEnv = ProviderHost.ProviderHost | McpProviderSessions.McpProviderSessions;

export const CopilotDriver: ProviderDriver<CopilotSettings, CopilotDriverEnv> = {
  driverKind,
  metadata: { displayName: "GitHub Copilot", supportsMultipleInstances: true },
  configSchema: CopilotSettings,
  defaultConfig: () => decodeSettings({}),
  create: Effect.fn("CopilotDriver.create")(function* ({
    instanceId,
    displayName,
    accentColor,
    environment,
    enabled,
    config,
  }) {
    const host = yield* ProviderHost.ProviderHost;
    const processEnv = yield* mergeProviderInstanceEnvironment(environment);
    const settings = { ...config, enabled };
    const configuration = yield* Effect.try({
      try: () =>
        resolveClientConfiguration({ settings, cwd: host.paths.cwd, environment: processEnv }),
      catch: (cause) =>
        new ProviderDriverError({
          driver: driverKind,
          instanceId,
          detail: "Could not configure Copilot.",
          cause,
        }),
    });
    const continuationIdentity = {
      driverKind,
      continuationKey: `githubCopilot:home:${configuration.effectiveHome}`,
    };
    const stamp = withInstanceIdentity({
      instanceId,
      driverKind,
      displayName,
      accentColor,
      continuationGroupKey: continuationIdentity.continuationKey,
    });
    const workspaceSkills = new Map<string, ReadonlyArray<ServerProviderSkill>>();
    const orchestrationAdapter = yield* makeAdapter(
      { instanceId, settings, environment: processEnv },
      {
        onSkills: (cwd, skills) => {
          if (skills) workspaceSkills.set(cwd, skills);
          else workspaceSkills.delete(cwd);
        },
      },
    );
    const snapshotSettings = yield* makeProviderSnapshotSettingsSource(settings);
    const snapshot = yield* makeManagedServerProvider({
      resolveMaintenance: () =>
        Effect.succeed(
          makeManualOnlyProviderMaintenanceCapabilities({
            provider: driverKind,
            packageName: "@github/copilot-sdk",
          }),
        ),
      getSettings: snapshotSettings.getSettings,
      streamSettings: snapshotSettings.streamSettings,
      haveSettingsChanged: haveProviderSnapshotSettingsChanged,
      initialSnapshot: () => pendingSnapshot(settings).pipe(Effect.map(stamp)),
      checkProvider: checkStatus(settings, host.paths.cwd, processEnv).pipe(Effect.map(stamp)),
    }).pipe(
      Effect.mapError(
        (cause) =>
          new ProviderDriverError({
            driver: driverKind,
            instanceId,
            detail: "Could not build Copilot provider snapshot.",
            cause,
          }),
      ),
    );
    const snapshotForCwd: NonNullable<ProviderInstance["snapshotForCwd"]> = Effect.fn(
      "CopilotDriver.snapshotForCwd",
    )(function* (cwd) {
      const current = yield* snapshot.getSnapshot;
      if (!enabled) return current;
      const cached = workspaceSkills.get(cwd);
      if (cached) return { ...current, skills: cached };
      const skills = yield* Effect.scoped(
        Effect.gen(function* () {
          const client = yield* Effect.acquireRelease(
            Effect.try({
              try: () =>
                createClient(
                  resolveClientConfiguration({ settings, cwd, environment: processEnv }).options,
                ),
              catch: (cause) =>
                new ProviderDriverError({
                  driver: driverKind,
                  instanceId,
                  detail: "Copilot discovery failed.",
                  cause,
                }),
            }),
            (client) =>
              Effect.gen(function* () {
                const stopped = yield* Effect.tryPromise(() => client.stop()).pipe(
                  Effect.timeoutOption(10_000),
                  Effect.result,
                );
                if (
                  stopped._tag === "Failure" ||
                  Option.isNone(stopped.success) ||
                  stopped.success.value.length
                ) {
                  yield* Effect.tryPromise(() => client.forceStop()).pipe(
                    Effect.timeoutOption(5_000),
                    Effect.ignore,
                  );
                }
              }),
          );
          return yield* Effect.tryPromise({
            try: async () => {
              await client.start();
              const discovered = await client.rpc.skills.discover({
                projectPaths: settings.enableConfigDiscovery ? [cwd] : [],
              });
              return skillsFromSdk(discovered.skills);
            },
            catch: (cause) =>
              new ProviderDriverError({
                driver: driverKind,
                instanceId,
                detail: "Copilot workspace skill discovery failed.",
                cause,
              }),
          });
        }),
      ).pipe(
        Effect.timeoutOption(30_000),
        Effect.flatMap((result) =>
          Effect.fromOption(result).pipe(
            Effect.mapError(
              (cause) =>
                new ProviderDriverError({
                  driver: driverKind,
                  instanceId,
                  detail: "Copilot discovery timed out.",
                  cause,
                }),
            ),
          ),
        ),
      );
      return { ...current, skills };
    });
    return {
      instanceId,
      driverKind,
      displayName,
      accentColor,
      enabled,
      continuationIdentity,
      snapshot,
      snapshotForCwd,
      orchestrationAdapter,
      textGeneration: makeTextGeneration(settings, processEnv),
    } satisfies ProviderInstance;
  }),
};

import { assert, describe, it } from "@effect/vitest";
import type { ModelInfo, SkillsLoadedSkill } from "@github/copilot-sdk";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import { CopilotSettings } from "../settings.ts";
import { checkStatus, modelsFromSdk, skillsFromSdk } from "./status.ts";
import { bundledCliPath, resolveClientConfiguration } from "./client.ts";

const decode = Schema.decodeSync(CopilotSettings);
const model = (id: string, extra: Partial<ModelInfo> = {}): ModelInfo => ({
  id,
  name: id,
  capabilities: {
    supports: { vision: true, reasoningEffort: true },
    limits: { max_context_window_tokens: 128_000 },
  },
  ...extra,
});
const skill = (
  name: string,
  source: SkillsLoadedSkill["source"],
  extra: Partial<SkillsLoadedSkill> = {},
): SkillsLoadedSkill => ({
  name,
  source,
  description: `${name} skill`,
  enabled: true,
  userInvocable: true,
  path: `/workspace/${name}/SKILL.md`,
  ...extra,
});

describe("Copilot discovery and account isolation", () => {
  it("keeps project/native skills in workspace results, including pathless built-ins", () => {
    const skills = skillsFromSdk([
      skill("project-skill", "project"),
      skill("personal-skill", "personal-copilot"),
      skill("builtin", "builtin", { path: "" }),
      skill("disabled", "project", { enabled: false }),
      skill("agent-only", "project", { userInvocable: false }),
      skill("project-skill", "personal-agents"),
    ]);
    assert.deepEqual(
      skills.map((entry) => entry.name),
      ["project-skill", "personal-skill", "builtin"],
    );
    assert.equal(skills[0]?.scope, "project");
    assert.equal(skills[2]?.path, "copilot://skills/builtin");
  });

  it("discovers allowed models and reasoning options without duplicates or policy-disabled models", () => {
    const result = modelsFromSdk(
      [
        model("gpt", {
          supportedReasoningEfforts: ["low", "high"],
          defaultReasoningEffort: "high",
        }),
        model("gpt"),
        model("blocked", { policy: { state: "disabled", terms: "" } }),
      ],
      decode({ customModels: ["custom"] }),
    );
    assert.deepEqual(
      result.map((entry) => entry.slug),
      ["gpt", "custom"],
    );
    assert.deepEqual(result[0]?.capabilities?.optionDescriptors?.[0], {
      id: "reasoningEffort",
      label: "Reasoning",
      type: "select",
      currentValue: "high",
      options: [
        { id: "low", label: "Low" },
        { id: "high", label: "High", isDefault: true },
      ],
    });
  });

  it("uses only the selected account's home and preserves SDK-owned native paths", () => {
    const first = resolveClientConfiguration({
      settings: decode({ homePath: "~/.copilot-work" }),
      cwd: "/workspace",
      environment: { HOME: "/accounts/first", COPILOT_HOME: "/ignored", GITHUB_TOKEN: "first" },
    });
    const second = resolveClientConfiguration({
      settings: decode({}),
      cwd: "/workspace",
      environment: { HOME: "/accounts/second", COPILOT_HOME: "/native/second" },
    });
    assert.equal(first.effectiveHome, "/accounts/first/.copilot-work");
    assert.equal(first.options.mode, "copilot-cli");
    assert.equal(first.options.baseDirectory, first.effectiveHome);
    assert.equal(first.options.env?.COPILOT_HOME, first.effectiveHome);
    assert.equal(second.effectiveHome, "/native/second");
    assert.isUndefined(second.options.env?.GITHUB_TOKEN);
  });

  it("resolves packaged Windows executables outside asar and Linux libc alternatives", () => {
    assert.equal(
      bundledCliPath({
        packaged: true,
        electron: true,
        platform: "win32",
        architecture: "x64",
        resolve: () => "C:\\T3\\app.asar\\node_modules\\@github\\copilot-win32-x64\\copilot.exe",
        exists: (path) => path.includes("app.asar.unpacked"),
      }),
      "C:\\T3\\app.asar.unpacked\\node_modules\\@github\\copilot-win32-x64\\copilot.exe",
    );
    assert.equal(
      bundledCliPath({
        packaged: true,
        electron: false,
        platform: "linux",
        architecture: "arm64",
        resolve: (name) => {
          if (!name.includes("linuxmusl")) throw new Error("not installed");
          return "/native/copilot";
        },
        exists: () => true,
      }),
      "/native/copilot",
    );
  });

  it.effect("returns authenticated SDK models without exposing any workspace skills globally", () =>
    Effect.gen(function* () {
      let stops = 0;
      const result = yield* checkStatus(
        decode({ enabled: true }),
        "/workspace",
        { HOME: "/account" },
        () => ({
          start: async () => {},
          stop: async () => {
            stops++;
            return [];
          },
          forceStop: async () => {},
          getStatus: async () => ({ version: "1.0.75", protocolVersion: 1 }),
          getAuthStatus: async () => ({ isAuthenticated: true, login: "octocat" }),
          listModels: async () => [model("gpt")],
        }),
      );
      assert.equal(result.status, "ready");
      assert.equal(result.auth.label, "octocat");
      assert.equal(result.models[0]?.slug, "gpt");
      assert.deepEqual(result.skills, []);
      assert.equal(stops, 1);
    }),
  );

  it.effect(
    "reports cleanup-only failures and preserves a primary probe failure when cleanup also fails",
    () =>
      Effect.gen(function* () {
        for (const failProbe of [false, true]) {
          let forced = 0;
          const snapshot = yield* checkStatus(decode({ enabled: true }), "/workspace", {}, () => ({
            start: async () => {},
            stop: async () => {
              throw new Error("stop failed");
            },
            forceStop: async () => {
              forced++;
            },
            getStatus: async () => {
              if (failProbe) throw new Error("probe failed");
              return { version: "1.0.75", protocolVersion: 1 };
            },
            getAuthStatus: async () => ({ isAuthenticated: true }),
            listModels: async () => [],
          }));
          assert.equal(snapshot.status, "error");
          assert.equal(forced, 1);
          assert.equal(
            snapshot.message,
            failProbe ? "GitHub Copilot status check failed." : "GitHub Copilot cleanup failed.",
          );
        }
      }),
  );
});

import type { CopilotClient, ModelInfo, SkillsLoadedSkill } from "@github/copilot-sdk";
import type { ServerProviderSkill } from "@t3tools/contracts";
import { createModelCapabilities } from "@t3tools/shared/model";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import {
  buildSelectOptionDescriptor,
  buildServerProvider,
  providerModelsFromSettings,
} from "@t3tools/provider-core/server/snapshotProbe";
import type { CopilotSettings } from "../settings.ts";
import { createClient, resolveClientConfiguration } from "./client.ts";

const presentation = {
  displayName: "GitHub Copilot",
  badgeLabel: "Preview",
  showInteractionModeToggle: true,
  supportsConversationRollback: false,
};
const emptyCapabilities = createModelCapabilities({ optionDescriptors: [] });

export function modelsFromSdk(models: ReadonlyArray<ModelInfo>, settings: CopilotSettings) {
  const seen = new Set<string>();
  return providerModelsFromSettings(
    models.flatMap((model) => {
      const slug = model.id.trim();
      if (!slug || !model.name.trim() || seen.has(slug) || model.policy?.state === "disabled")
        return [];
      seen.add(slug);
      const efforts = model.supportedReasoningEfforts ?? [];
      return [
        {
          slug,
          name: model.name,
          isCustom: false,
          ...(seen.size === 1 ? { isDefault: true } : {}),
          capabilities: createModelCapabilities({
            optionDescriptors: efforts.length
              ? [
                  buildSelectOptionDescriptor({
                    id: "reasoningEffort",
                    label: "Reasoning",
                    options: efforts.map((effort) => ({
                      value: effort,
                      label:
                        effort === "xhigh"
                          ? "Extra High"
                          : effort[0]!.toUpperCase() + effort.slice(1),
                      isDefault: effort === model.defaultReasoningEffort,
                    })),
                  }),
                ]
              : [],
          }),
        },
      ];
    }),
    settings.customModels,
    emptyCapabilities,
  );
}

// Workspace snapshots are requested with a cwd; no project skills enter the instance snapshot.
export function skillsFromSdk(
  skills: ReadonlyArray<SkillsLoadedSkill>,
): ReadonlyArray<ServerProviderSkill> {
  const seen = new Set<string>();
  return skills.flatMap((skill) => {
    const name = skill.name.trim();
    if (!name || !skill.enabled || !skill.userInvocable || seen.has(name)) return [];
    seen.add(name);
    return [
      {
        name,
        ...(skill.description.trim() ? { description: skill.description } : {}),
        path: skill.path?.trim() || `copilot://skills/${encodeURIComponent(name)}`,
        enabled: true,
        scope: skill.source,
        userInvocable: true,
      },
    ];
  });
}

export const pendingSnapshot = (settings: CopilotSettings) =>
  DateTime.now.pipe(
    Effect.map((now) =>
      buildServerProvider({
        presentation,
        enabled: settings.enabled,
        checkedAt: DateTime.formatIso(now),
        models: modelsFromSdk([], settings),
        probe: {
          installed: false,
          version: null,
          status: "warning",
          auth: { status: "unknown" },
          message: settings.enabled
            ? "Checking GitHub Copilot availability..."
            : "GitHub Copilot is disabled.",
        },
      }),
    ),
  );

export type StatusClient = Pick<
  CopilotClient,
  "start" | "stop" | "forceStop" | "getStatus" | "getAuthStatus" | "listModels"
>;

export const checkStatus = Effect.fn("Copilot.checkStatus")(function* (
  settings: CopilotSettings,
  cwd: string,
  environment: NodeJS.ProcessEnv,
  factory: (
    options: ReturnType<typeof resolveClientConfiguration>["options"],
  ) => StatusClient = createClient,
) {
  if (!settings.enabled) return yield* pendingSnapshot(settings);
  let started = false;
  let cleanupFailed = false;
  const checkedAt = DateTime.formatIso(yield* DateTime.now);
  const result = yield* Effect.scoped(
    Effect.gen(function* () {
      const client = yield* Effect.acquireRelease(
        Effect.try(() =>
          factory(resolveClientConfiguration({ settings, cwd, environment }).options),
        ),
        (client) =>
          Effect.gen(function* () {
            const stopped = yield* Effect.tryPromise(() => client.stop()).pipe(
              Effect.timeoutOption(10_000),
              Effect.result,
            );
            if (
              stopped._tag === "Failure" ||
              Option.isNone(stopped.success) ||
              stopped.success.value.length
            ) {
              cleanupFailed = true;
              yield* Effect.tryPromise(() => client.forceStop()).pipe(
                Effect.timeoutOption(5_000),
                Effect.ignore,
              );
            }
          }),
      );
      return yield* Effect.tryPromise(async () => {
        await client.start();
        started = true;
        const [status, auth] = await Promise.all([client.getStatus(), client.getAuthStatus()]);
        const models = auth.isAuthenticated ? await client.listModels() : [];
        return { status, auth, models };
      });
    }),
  ).pipe(Effect.timeoutOption(30_000), Effect.result);
  if (result._tag === "Failure" || Option.isNone(result.success) || cleanupFailed) {
    return buildServerProvider({
      presentation,
      enabled: true,
      checkedAt,
      models: modelsFromSdk([], settings),
      probe: {
        installed: started,
        version: null,
        status: "error",
        auth: { status: "unknown" },
        message:
          cleanupFailed && result._tag === "Success" && Option.isSome(result.success)
            ? "GitHub Copilot cleanup failed."
            : started
              ? "GitHub Copilot status check failed."
              : "Unable to start the Copilot CLI.",
      },
    });
  }
  const { status, auth, models } = result.success.value;
  return buildServerProvider({
    presentation,
    enabled: true,
    checkedAt,
    models: modelsFromSdk(models, settings),
    probe: {
      installed: true,
      version: status.version,
      status: auth.isAuthenticated ? "ready" : "error",
      auth: auth.isAuthenticated
        ? { status: "authenticated", ...(auth.login ? { label: auth.login } : {}) }
        : { status: "unauthenticated" },
      ...(!auth.isAuthenticated
        ? { message: "Sign in with `copilot login` in this provider's account environment." }
        : {}),
    },
  });
});

import { assert, describe, it } from "@effect/vitest";
import type { SessionConfig } from "@github/copilot-sdk";
import { ProviderInstanceId } from "@t3tools/contracts";
import * as Effect from "effect/Effect";
import * as Exit from "effect/Exit";
import * as Fiber from "effect/Fiber";
import * as Schema from "effect/Schema";
import { CopilotSettings } from "../settings.ts";
import { makeTextGeneration } from "./textGeneration.ts";

const settings = Schema.decodeSync(CopilotSettings)({});

function gate() {
  let resolve!: () => void;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

describe("Copilot background text generation", () => {
  it.effect(
    "uses a tool-free native session, validates JSON and deletes only its owned ephemeral session",
    () =>
      Effect.gen(function* () {
        let config: SessionConfig | undefined;
        const cleanup: string[] = [];
        const generation = makeTextGeneration(
          settings,
          { HOME: "/account" },
          {
            clientFactory: (options) => {
              assert.equal(options.mode, "copilot-cli");
              return {
                start: async () => {},
                stop: async () => {
                  cleanup.push("stop");
                  return [];
                },
                forceStop: async () => {},
                deleteSession: async (id) => {
                  cleanup.push(`delete:${id}`);
                },
                createSession: async (created) => {
                  config = created;
                  return {
                    sessionId: "ephemeral",
                    disconnect: async () => {
                      cleanup.push("disconnect");
                    },
                    sendAndWait: async () =>
                      ({
                        type: "assistant.message",
                        data: { content: '{"title":"Native title"}' },
                      }) as Awaited<
                        ReturnType<import("@github/copilot-sdk").CopilotSession["sendAndWait"]>
                      >,
                  };
                },
              };
            },
          },
        );
        const result = yield* generation.generateThreadTitle({
          cwd: "/workspace",
          message: "Title this work",
          modelSelection: {
            instanceId: ProviderInstanceId.make("githubCopilot"),
            model: "gpt-4.1",
            options: [],
          },
        });
        assert.equal(result.title, "Native title");
        assert.deepEqual(config?.availableTools, []);
        assert.deepEqual(config?.mcpServers, {});
        assert.isFalse(config!.enableConfigDiscovery);
        assert.isFalse(config!.enableSkills);
        assert.deepEqual(cleanup, ["disconnect", "delete:ephemeral", "stop"]);
      }),
  );

  it.effect("rejects malformed generation output while still cleaning up native resources", () =>
    Effect.gen(function* () {
      let deleted = 0;
      let stopped = 0;
      const generation = makeTextGeneration(
        settings,
        {},
        {
          clientFactory: () => ({
            start: async () => {},
            stop: async () => {
              stopped++;
              return [];
            },
            forceStop: async () => {},
            deleteSession: async () => {
              deleted++;
            },
            createSession: async () => ({
              sessionId: "ephemeral",
              disconnect: async () => {},
              sendAndWait: async () =>
                ({ type: "assistant.message", data: { content: "not JSON" } }) as Awaited<
                  ReturnType<import("@github/copilot-sdk").CopilotSession["sendAndWait"]>
                >,
            }),
          }),
        },
      );
      const result = yield* generation
        .generateBranchName({
          cwd: "/workspace",
          message: "Fix native session lifecycle",
          modelSelection: {
            instanceId: ProviderInstanceId.make("githubCopilot"),
            model: "gpt-4.1",
            options: [],
          },
        })
        .pipe(Effect.exit);
      assert.isTrue(Exit.isFailure(result));
      assert.equal(deleted, 1);
      assert.equal(stopped, 1);
    }),
  );

  it.effect("never sends after cancellation while a native session is being created", () =>
    Effect.gen(function* () {
      const creating = gate();
      const release = gate();
      const cleaned = gate();
      let sent = 0;
      let deleted = 0;
      let stopped = 0;
      const generation = makeTextGeneration(
        settings,
        {},
        {
          clientFactory: () => ({
            start: async () => {},
            stop: async () => {
              stopped++;
              return [];
            },
            forceStop: async () => {},
            deleteSession: async () => {
              deleted++;
              cleaned.resolve();
            },
            createSession: async () => {
              creating.resolve();
              await release.promise;
              return {
                sessionId: "late-session",
                disconnect: async () => {},
                sendAndWait: async () => {
                  sent++;
                  return undefined;
                },
              };
            },
          }),
        },
      );
      const pending = yield* Effect.forkChild(
        generation.generateThreadTitle({
          cwd: "/workspace",
          message: "Title",
          modelSelection: {
            instanceId: ProviderInstanceId.make("githubCopilot"),
            model: "gpt-4.1",
            options: [],
          },
        }),
      );
      yield* Effect.promise(() => creating.promise);
      yield* Fiber.interrupt(pending);
      assert.equal(stopped, 1);
      release.resolve();
      yield* Effect.promise(() => cleaned.promise);
      assert.equal(deleted, 1);
      assert.equal(sent, 0);
    }),
  );
});

import type {
  CopilotClient,
  CopilotClientOptions,
  CopilotSession,
  SessionConfig,
} from "@github/copilot-sdk";
import { TextGenerationError } from "@t3tools/contracts";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as TextGenerationOperations from "@t3tools/provider-core/server/textGenerationOperations";
import type { CopilotSettings } from "../settings.ts";
import { createClient, resolveClientConfiguration } from "./client.ts";
import { reasoningEffort } from "./adapter.ts";

type GenerationSession = Pick<CopilotSession, "sessionId" | "sendAndWait" | "disconnect">;
type GenerationClient = Pick<CopilotClient, "start" | "stop" | "forceStop" | "deleteSession"> & {
  readonly createSession: (config: SessionConfig) => Promise<GenerationSession>;
};
export interface GenerationOptions {
  readonly clientFactory?: (options: CopilotClientOptions) => GenerationClient;
}

export function makeTextGeneration(
  settings: CopilotSettings,
  environment: NodeJS.ProcessEnv,
  options: GenerationOptions = {},
) {
  const run: TextGenerationOperations.Runner = Effect.fn("CopilotTextGeneration.run")(
    function* (request) {
      const error = (cause?: unknown) =>
        new TextGenerationError({
          operation: request.operation,
          detail: "GitHub Copilot text generation failed.",
          cause,
        });
      let cleanupFailed = false;
      let forceRequired = false;
      const generated = yield* Effect.scoped(
        Effect.gen(function* () {
          const client = yield* Effect.try({
            try: () =>
              (options.clientFactory ?? createClient)(
                resolveClientConfiguration({ settings, cwd: request.cwd, environment }).options,
              ),
            catch: error,
          });
          let session: GenerationSession | undefined;
          let finalized = false;
          const call = <A>(stage: string, operation: () => Promise<A>, timeoutMs: number) =>
            Effect.tryPromise({ try: operation, catch: error }).pipe(
              Effect.timeoutOption(timeoutMs),
              Effect.flatMap((result) =>
                Effect.fromOption(result).pipe(
                  Effect.mapError(() => {
                    forceRequired = true;
                    return new TextGenerationError({
                      operation: request.operation,
                      detail: `GitHub Copilot text generation ${stage} timed out.`,
                    });
                  }),
                ),
              ),
            );
          const cleanup = <A>(operation: () => Promise<A>, timeoutMs = 5_000) =>
            Effect.tryPromise(operation).pipe(Effect.timeoutOption(timeoutMs), Effect.result);
          yield* Effect.addFinalizer(() =>
            Effect.gen(function* () {
              if (finalized) return;
              finalized = true;
              const owned = session;
              session = undefined;
              if (owned) {
                const disconnected = yield* cleanup(() => owned.disconnect());
                const deleted = yield* cleanup(() => client.deleteSession(owned.sessionId));
                if (
                  disconnected._tag === "Failure" ||
                  Option.isNone(disconnected.success) ||
                  deleted._tag === "Failure" ||
                  Option.isNone(deleted.success)
                )
                  cleanupFailed = true;
              }
              const stopped = yield* cleanup(() => client.stop(), 10_000);
              if (
                stopped._tag === "Failure" ||
                Option.isNone(stopped.success) ||
                stopped.success.value.length
              ) {
                cleanupFailed = true;
              }
              if (cleanupFailed || forceRequired) yield* cleanup(() => client.forceStop());
            }),
          );
          yield* call("startup", () => client.start(), 30_000);
          const effort = reasoningEffort(request.modelSelection);
          const owned = yield* call(
            "session creation",
            () =>
              client
                .createSession({
                  clientName: "t3-code-text-generation",
                  workingDirectory: request.cwd,
                  model: request.modelSelection.model,
                  ...(effort ? { reasoningEffort: effort } : {}),
                  streaming: false,
                  enableConfigDiscovery: false,
                  enableSkills: false,
                  availableTools: [],
                  mcpServers: {},
                  customAgents: [],
                  skipCustomInstructions: true,
                  requestExtensions: false,
                  requestCanvasRenderer: false,
                  enableMcpApps: false,
                  manageScheduleEnabled: false,
                  infiniteSessions: { enabled: false },
                  onPermissionRequest: () => ({ kind: "reject" }),
                })
                .then(async (created) => {
                  if (finalized) {
                    try {
                      await created.disconnect();
                    } finally {
                      await client.deleteSession(created.sessionId);
                    }
                    throw new Error("Copilot session creation completed after cancellation.");
                  }
                  session = created;
                  return created;
                }),
            30_000,
          );
          const reply = yield* call(
            "response",
            () => owned.sendAndWait({ prompt: request.prompt }, 180_000),
            180_000,
          );
          const output = reply?.data.content ?? "";
          if (output.length > 20_000)
            return yield* new TextGenerationError({
              operation: request.operation,
              detail: "GitHub Copilot returned oversized structured output.",
            });
          return yield* TextGenerationOperations.decodeJsonReply(request, "GitHub Copilot", output);
        }),
      );
      if (cleanupFailed)
        return yield* new TextGenerationError({
          operation: request.operation,
          detail: "GitHub Copilot text generation cleanup failed.",
        });
      return generated;
    },
  );
  return TextGenerationOperations.fromRunner(
    "CopilotTextGeneration",
    TextGenerationOperations.withoutInvestigation("GitHub Copilot", run),
  );
}

import type { SessionEvent } from "@github/copilot-sdk";
import type { OrchestrationV2TurnItem } from "@t3tools/contracts";

type ToolStart = Extract<SessionEvent, { type: "tool.execution_start" }>["data"];
type Base = Omit<
  Extract<OrchestrationV2TurnItem, { type: "dynamic_tool" }>,
  "type" | "toolName" | "input" | "output"
>;
const sensitive = /authorization|cookie|credential|password|secret|token/iu;
const binary = /^(?:base64|bytes|binaryResultsForLlm|contents)$/u;

export function boundedToolJson(value: unknown): string {
  try {
    return (
      JSON.stringify(value, (key, entry: unknown) => {
        if (sensitive.test(key)) return "[redacted]";
        if (binary.test(key)) return "[omitted]";
        if (typeof entry === "string") return entry.slice(0, 4_000);
        if (Array.isArray(entry)) return entry.slice(0, 64);
        return entry;
      }) ?? ""
    ).slice(0, 8_000);
  } catch {
    return "[unavailable]";
  }
}

function argument(data: ToolStart, keys: ReadonlyArray<string>): string | undefined {
  for (const key of keys) {
    const value = data.arguments?.[key];
    if (typeof value === "string" && value.trim()) return value.slice(0, 8_000);
  }
  return undefined;
}

export function nativeToolItem(base: Base, data: ToolStart): OrchestrationV2TurnItem {
  const toolName = data.toolName.toLowerCase();
  if (!data.mcpServerName && /shell|bash|powershell|command/u.test(toolName)) {
    return {
      ...base,
      type: "command_execution",
      input: argument(data, ["command", "cmd", "script"]) ?? data.toolName,
    };
  }
  const path = argument(data, ["path", "filePath", "filename", "fileName", "file_name"]);
  if (!data.mcpServerName && /write|edit|patch|create/u.test(toolName) && path) {
    const before = argument(data, ["old_str", "oldString"]);
    const after = argument(data, ["new_str", "newString", "file_text", "content"]);
    return {
      ...base,
      type: "file_change",
      fileName: path,
      ...(before ? { oldStr: before } : {}),
      ...(after ? { newStr: after } : {}),
    };
  }
  if (!data.mcpServerName && /web|search/u.test(toolName)) {
    const query = argument(data, ["query", "search_query", "pattern"]);
    return { ...base, type: "web_search", ...(query ? { patterns: [query] } : {}) };
  }
  return {
    ...base,
    type: "dynamic_tool",
    toolName: data.toolName,
    title: data.mcpServerName
      ? `${data.mcpServerName}: ${data.mcpToolName ?? data.toolName}`
      : base.title,
    input: boundedToolJson(data.arguments ?? {}),
  };
}

import {
  CustomModelSetting,
  TrimmedString,
  makeBinaryPathSetting,
  makeProviderSettingsSchema,
} from "@t3tools/contracts";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";

export const CopilotSettings = makeProviderSettingsSchema(
  {
    enabled: Schema.Boolean.pipe(
      Schema.withDecodingDefault(Effect.succeed(false)),
      Schema.annotateKey({ providerSettingsForm: { hidden: true } }),
    ),
    binaryPath: makeBinaryPathSetting("copilot").pipe(
      Schema.annotateKey({
        title: "Binary path",
        description: "Optional CLI override. Leave as copilot to use the SDK's bundled executable.",
        providerSettingsForm: { placeholder: "copilot", clearWhenEmpty: "omit" },
      }),
    ),
    homePath: TrimmedString.pipe(
      Schema.withDecodingDefault(Effect.succeed("")),
      Schema.annotateKey({
        title: "COPILOT_HOME path",
        description: "Copilot account, session and configuration directory.",
        providerSettingsForm: { placeholder: "~/.copilot", clearWhenEmpty: "omit" },
      }),
    ),
    enableConfigDiscovery: Schema.Boolean.pipe(
      Schema.withDecodingDefault(Effect.succeed(true)),
      Schema.annotateKey({
        title: "Discover project configuration",
        description: "Load project MCP servers, skills and instructions.",
        providerSettingsForm: { control: "switch" },
      }),
    ),
    customModels: Schema.Array(CustomModelSetting).pipe(
      Schema.withDecodingDefault(Effect.succeed([])),
      Schema.annotateKey({ providerSettingsForm: { hidden: true } }),
    ),
  },
  { order: ["binaryPath", "homePath", "enableConfigDiscovery"] },
);
export type CopilotSettings = typeof CopilotSettings.Type;

